:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8a9a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #1f1f3a 25%, transparent 25%),
                    linear-gradient(-45deg, #1f1f3a 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #1f1f3a 75%),
                    linear-gradient(-45deg, transparent 75%, #1f1f3a 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  padding: 32px 24px;
  border: 4px solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 #0f0f1a;
  width: 100%;
  max-width: 420px;
  image-rendering: pixelated;
}

h1 {
  margin: 0 0 24px;
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent);
  text-align: center;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--muted);
}

input, select, button, output {
  width: 100%;
  padding: 12px;
  margin-bottom: 18px;
  font-family: inherit;
  font-size: 1rem;
  border: 3px solid var(--muted);
  border-radius: 0;
  background: #0f0f1a;
  color: var(--text);
  outline: none;
}

input:focus, select:focus, button:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.4);
}

input:hover, select:hover {
  border-color: var(--text);
}

button {
  background: var(--accent);
  color: #fff;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  border-color: var(--accent);
  transition: transform 0.05s, background 0.15s;
}

button:hover {
  background: #ff5c7a;
  border-color: #ff5c7a;
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.formula {
  font-size: 0.8rem;
  color: var(--muted);
  text-align: center;
  margin: -8px 0 18px;
  word-break: break-word;
}

output {
  display: block;
  text-align: center;
  font-size: 1.5rem;
  font-weight: bold;
  border-color: var(--accent);
  margin-bottom: 0;
  min-height: 3rem;
  color: var(--accent);
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 1.25rem; }
  input, select, button, output { padding: 10px; }
}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('converter');
  const tempInput = document.getElementById('temperature');
  const direction = document.getElementById('direction');
  const result = document.getElementById('result');

  function convert() {
    const raw = tempInput.value.trim();
    const x = Number(raw);
    if (raw === '' || !Number.isFinite(x)) {
      result.textContent = 'Error';
      return;
    }
    let value;
    if (direction.value === 'c-to-f') {
      value = x * 9 / 5 + 32;
    } else {
      value = (x - 32) * 5 / 9;
    }
    result.textContent = value.toFixed(2);
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    convert();
  });

  tempInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      convert();
    }
  });
});
